from pathlib import Path
import subprocess,json,os
root=Path('/srv/projects/iptvpn-bot')
p=root/'ecosystem.config.js'
old="/root/iptvpn_bot"
new="/srv/projects/iptvpn-bot"
def cmd(args,t=15):
 return subprocess.run(args,capture_output=True,text=True,timeout=t)
def pm():
 r=cmd(['pm2','jlist'],15)
 if r.returncode:raise RuntimeError('PM2 state not accessible')
 return {a.get('name'):{'status':(a.get('pm2_env') or {}).get('status'),'pid':a.get('pid')} for a in json.loads(r.stdout) if a.get('name') in ('iptvpn_bot','telegram-robot-leads')}
before=pm()
if any(before.get(n,{}).get('status')!='online' for n in ('iptvpn_bot','telegram-robot-leads')):raise RuntimeError('Bot offline at start')
if not root.is_dir() or root.is_symlink() or not p.is_file() or p.is_symlink():raise RuntimeError('IPTVPN project file mismatch')
r=cmd(['git','-C',str(root),'remote','get-url','origin'],15)
if r.returncode or 'martaxi-boss/iptvpn-bot' not in r.stdout:raise RuntimeError('Git origin unexpected')
original=p.read_bytes()
a=original.count(old.encode());b=original.count(new.encode())
if a==0 and b>0:
 print('IPTVPN_ECOSYSTEM_ALREADY_CANONICAL=YES')
elif a==1 and b==0:
 try:
  p.write_bytes(original.replace(old.encode(),new.encode()))
  t=cmd(['node','--check',str(p)],14)
  if t.returncode:raise RuntimeError('Syntax invalid after canonical path update')
  t=cmd(['git','-C',str(root),'diff','--check','--','ecosystem.config.js'],15)
  if t.returncode:raise RuntimeError('Git diff whitespace validation failed')
  if pm()!=before:raise RuntimeError('PM2 bot status or PID changed')
 except Exception:
  p.write_bytes(original)
  print('IPTVPN_ECOSYSTEM_ROLLBACK=APPLIED')
  raise
 print('IPTVPN_ECOSYSTEM_UPDATED_TO='+new)
else:raise RuntimeError('Unexpected number of hardcoded legacy/canonical references')
if cmd(['node','--check',str(p)],14).returncode:raise RuntimeError('Final PM2 ecosystem syntax failed')
print('PM2_BOTS_PIDS_UNCHANGED=YES')
print('PM2_CONFIG_SYNTAX=PASS')
print('IPTVPN_ECOSYSTEM_CANONICAL=PASS')
PY
